import{_ as l,r as n,o as p,c,e as t,a as e,d as s,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Setting Up the Scheduler - October CMS - 3.x","titleTemplate":false,"description":"Learn how to run scheduled tasks and queues.","frontmatter":{"subtitle":"Learn how to run scheduled tasks and queues."},"headers":[{"level":2,"title":"Setting Up Queue Workers","slug":"setting-up-queue-workers","link":"#setting-up-queue-workers","children":[]},{"level":2,"title":"Cron Without Command Line","slug":"cron-without-command-line","link":"#cron-without-command-line","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/setup/scheduler.md","filePath":"3.x/setup/scheduler.md"}'),u={name:"3.x/setup/scheduler.md"};function d(h,a,g,m,k,f){const o=n("pre-heading"),r=n("post-heading");return p(),c("div",null,[t(o),a[0]||(a[0]=e("h1",null,"Setting Up the Scheduler",-1)),t(r),a[1]||(a[1]=e("p",null,[s("For scheduled tasks to operate correctly, add the following "),e("a",{href:"https://www.cyberciti.biz/faq/how-do-i-add-jobs-to-cron-under-linux-or-unix-oses/",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("Cron job"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),e("span",{class:"sr-only"},"(opens new window)")])]),s(" to the server:")],-1)),a[2]||(a[2]=i(`<div class="language-bash extra-class"><pre class="language-bash"><code>* * * * * php /october/artisan schedule:run <span class="token operator">&gt;&gt;</span> /dev/null <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre></div><p>Be sure to replace <code>/october/artisan</code> with the absolute path to the artisan file in the October CMS installation directory. This cron job will call the command scheduler every minute. Then October CMS evaluates any scheduled tasks and runs the due tasks.</p><div class="custom-block tip"><p>When adding a crontab file to /etc/cron.d, specify a user name after <code>* * * * *</code>:</p><div class="language-bash extra-class"><pre class="language-bash"><code>* * * * * alice php /october/artisan schedule:run <span class="token operator">&gt;&gt;</span> /dev/null <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre></div></div><h2 id="setting-up-queue-workers"><a href="#setting-up-queue-workers" class="header-anchor">#</a> Setting Up Queue Workers</h2><p>You may optionally set up a queue driver for processing <a href="./../extend/services/queue.html">queued jobs</a>. The queue driver can be configured in the <code>config/queue.php</code> file.</p><p>For the database queue driver, you can set up a cron job running the command that invokes the first job available in the queue: <code>php artisan queue:work --once</code>.</p><div class="language-bash extra-class"><pre class="language-bash"><code>* * * * * php /october/artisan queue:work <span class="token parameter variable">--once</span> <span class="token operator">&gt;&gt;</span> /dev/null <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre></div><p>Alternatively, it is possible to run the queue as a daemon process with</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan queue:work
</code></pre></div><h2 id="cron-without-command-line"><a href="#cron-without-command-line" class="header-anchor">#</a> Cron Without Command Line</h2><p>If the cron table is not made available by your web host, you can instead call a public URL every X number of minutes. For example, if a plugin requires that you run the following command every 15 minutes.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan campaign:run
</code></pre></div><p>This requires some PHP coding as a solution, using the <code>Artisan</code> facade along with a <a href="./../extend/system/routing.html">routes file</a> to build an endpoint that calls this command. For example, a <strong>routes.php</strong> file may contain the following.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/campaign-run&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Artisan</span><span class="token operator">::</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;campaign:run&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When opening the URL <code>/campaign-run</code> the artisan command will be called.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../extend/system/scheduling.html">Task Scheduling</a></li><li><a href="./../extend/services/queue.html">Queues</a></li></ul></div>`,17))])}const w=l(u,[["render",d]]);export{b as __pageData,w as default};
